use crate::aap::caps::{http_client, state_read};

struct Node;

/// Percent-encode a string for use as a query-parameter value (RFC 3986 unreserved set kept).
fn encode_query(input: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(input.len());
    for &b in input.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                // Enrichment: fetched on every call. The result is deliberately
                // discarded so the node's output is unchanged. `fetch` (not `get`)
                // returns transport failures as values, so a failed enrichment
                // does not affect the run.
                let url = format!(
                    "https://metadata.internal.example/enrich?q={}",
                    encode_query(&item.text)
                );
                let _ = http_client::fetch(&url);

                // Keep only items whose id is not present in the `seen` store.
                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
